import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"TLS, вход и права","description":"","frontmatter":{"pageId":"admins/security-auth","contentRevision":2},"headers":[],"relativePath":"ru/admins/security-auth.md","filePath":"ru/admins/security-auth.md"}'),o={name:"ru/admins/security-auth.md"};function n(s,a,d,l,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="tls-вход-и-права" tabindex="-1">TLS, вход и права <a class="header-anchor" href="#tls-вход-и-права" aria-label="Permalink to &quot;TLS, вход и права&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>TLS по умолчанию включён. Укажи PEM CertificatePath/KeyPath либо используй самоподписанный сертификат; его pin сообщай игрокам независимым каналом. SelfSignedPath задаёт путь самоподписанного сертификата. Планируй ротацию заранее.</p><p>Steam-вход требует SteamWebApiKey и соответствующих Steam id для административных аккаунтов. Парольный вход включается AllowPassword; AdminLogins назначает первоначальных администраторов. Общий ServerPassword не заменяет личную аутентификацию.</p><p>Для интеграций используй отдельные Admin:Tokens с Name, Token, Scopes. Имя уникально, [a-z0-9-], до 32 символов; токен уникален, не короче 24. read читает, moderate включает read, chat разрешает внешнее сообщение, admin даёт все права. Минимизируй scope.</p><h2 id="rotate-access" tabindex="-1">Разделение и отзыв доступа интеграций <a class="header-anchor" href="#rotate-access" aria-label="Permalink to &quot;Разделение и отзыв доступа интеграций {#rotate-access}&quot;">​</a></h2><p>Выдай мониторингу read, чат-мосту read+chat, модерации moderate по необходимости. moderate включает read, но не chat; admin даёт всё. Для каждого процесса создай отдельное имя/секрет. При отзыве одного не нужно менять все остальные. Изменения конфигурации применяй контролируемым перезапуском и проверкой отказа отозванного токена.</p><p>Панель использует только legacy Admin:ApiToken: named token не даёт вход в браузер даже со scope admin. Перезапуск завершает cookie-сессии. Для cookie-мутаций нужны X-Rimlink-Panel: 1 и допустимый Origin; Bearer-интеграции не должны эмулировать cookie.</p><p>Не передавай токены в URL. CLI --token может остаться в history/списке процессов: используй защищённое окружение оператора и не снимай полный командный журнал в публичный отчёт.</p><h2 id="rotate-cert" tabindex="-1">Плановая замена сертификата <a class="header-anchor" href="#rotate-cert" aria-label="Permalink to &quot;Плановая замена сертификата {#rotate-cert}&quot;">​</a></h2><p>До замены сохрани рабочую конфигурацию и объяви новый pin доверенным каналом. После перезапуска сравни фактически отданный сертификат с объявленным и проверь игровой клиент и бота. У клиента старый pin должен потребовать решения, а не молча обновиться.</p><p>Если игрок получил неожиданный новый pin, сначала проверь адрес/NAT/proxy и факт ротации. Не советуй массово включить --insecure или доверять любому сертификату. SelfSignedPath по умолчанию зависит от DataDir; случайный пустой mount может выглядеть как «ротация» нового сервера.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Панель использует legacy Admin:ApiToken, не именованные токены. Cookie HttpOnly/Secure/SameSite=Strict, сессии в памяти сбрасываются рестартом; 5 неудач блокируют IP на 10 минут. Cookie-мутации требуют CSRF. Не используй --insecure вне изолированного теста. X-Rimlink-Actor — аудитная подпись 1–64 символа без control, не доказательство личности.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./api">Справочник REST API</a></li><li><a href="./administration">Панель и модерация</a></li><li><a href="./discord">Discord-бот</a></li></ul>',17)])])}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
